import{A as e,H as t,V as n,et as r}from"./chunks/framework.B1PU1n-w.js";var i=JSON.parse(`{"title":"安装","description":"","frontmatter":{},"headers":[],"relativePath":"quick-start/installation.md","filePath":"quick-start/installation.md"}`),a={name:`quick-start/installation.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to “安装”">​</a></h1><h2 id="安装-syncraft-server" tabindex="-1">安装 syncraft-server <a class="header-anchor" href="#安装-syncraft-server" aria-label="Permalink to “安装 syncraft-server”">​</a></h2><p>（暂时没有构建发布到任何平台）</p><p>以下，让我们假设 syncraft-server 已经添加到您的系统，并可以用命令 <code>syncraft</code> 访问。</p><h2 id="初始化工作区" tabindex="-1">初始化工作区 <a class="header-anchor" href="#初始化工作区" aria-label="Permalink to “初始化工作区”">​</a></h2><p>切换到你的 Minecraft 目录下，在终端中运行：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">syncraft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div><p>这会进入交互式配置流程，syncraft 会推断出它能推断的信息，另有一些信息需要你自己填写。</p><p>如果初始化因某些原因失败，你可以添加 <code>--force</code> 来移除工作区并重新初始化。</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">syncraft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span></span></code></pre></div><p>syncraft 的初始化会在你的 Minecraft 服务器目录下创建 <code>syncraft.toml</code> 和 <code>syncraft/</code>，前者是 syncraft 的配置文件，后者是 syncraft 和 yggdrasil 的数据目录。</p><h2 id="安装服务" tabindex="-1">安装服务 <a class="header-anchor" href="#安装服务" aria-label="Permalink to “安装服务”">​</a></h2><p>syncraft-server 可以以系统服务的形式安装在系统中。在终端内运行：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">syncraft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>软件将会写入服务并自动启动守护进程。你的机器重启时，syncraft-server 也会自动启动。你可以用以下命令管理守护进程：</p><p>关闭守护进程：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">syncraft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span></span></code></pre></div><p>启动守护进程：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">syncraft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>或</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">syncraft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><p>如果出于测试目的想让软件在前台运行，那么可以使用：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">syncraft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>如果你想卸载服务，运行：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">syncraft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>如果你不运行 <code>syncraft serve install</code> 安装服务，或者你的机器没有服务管理器，那么 syncraft 将会以内置守护线程实现的方式运行，这更加不稳定，但也可以用。</p></div><h2 id="安装-authlib-injector" tabindex="-1">安装 authlib-injector <a class="header-anchor" href="#安装-authlib-injector" aria-label="Permalink to “安装 authlib-injector”">​</a></h2><p>authlib-injector 是一个 Java 代理，可以将原本写死在 Minecraft 中的验证服务器地址更换为社区提供的 Yggdrasil 服务。对于 syncraft 的账号管理功能是必要的。</p><p>在客户端，syncraft-core 会自动配置 authlib-injector。在服务端。syncraft-server 也提供了一个指令，在大多数情况下它可以帮您安装 authlib-injector。</p><p>在服务器目录下运行：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">syncraft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> authlib</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inject</span></span></code></pre></div><p>这个指令会自动下载 authlib-injector，并为你修改启动脚本（若原本有）或生成启动脚本（若原本没有）。</p><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>这个指令会将 authlib-injector 的地址设置为 <code>http://127.0.0.1:&lt;port&gt;/yggdrasil</code>，因为一般情况下 syncraft-server 和你的 Minecraft 服务器应该是运行在同一台机器上的。</p></div><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>你仍然需要自己启动服务器，syncraft-server 不负责 Minecraft 服务器的启动。</p></div><p>如果你认为该指令错误地配置了你的服务器，运行以下指令卸载安装：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">syncraft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> authlib</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span></span></code></pre></div><p>如果你想要手动安装，建议阅读 <a href="https://manual.littlesk.in/yggdrasil/authlib-injector" target="_blank" rel="noreferrer">Littleskin 的教程</a>。该教程中的链接配置为 <code>littleskin.cn</code>，请根据你配置 syncraft-server 的情况作出修改。</p>`,37)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};